ass="text-lg font-bold">Create staff account</h2><div class="mt-4 space-y-3">@foreach([['first_name','First name'],['middle_name','Middle name (optional)'],['last_name','Last name'],['suffix','Suffix (optional)'],['email','Email'],['phone_number','Philippine phone number'],['position','Position (optional)'],['department','Department (optional)']] as [$name,$label])<label class="block text-sm font-semibold">{{ $label }}<input name="{{ $name }}" value="{{ old($name) }}" @if(!str_contains($label,'optional')) required @endif class="mt-1 w-full rounded-xl border border-navy/15 p-2.5"></label>@endforeach<label class="block text-sm font-semibold">Temporary password<input type="password" name="password" required class="mt-1 w-full rounded-xl border border-navy/15 p-2.5"></label><label class="block text-sm font-semibold">Confirm password<input type="password" name="password_confirmation" required class="mt-1 w-full rounded-xl border border-navy/15 p-2.5"></label><input type="hidden" name="status" value="active"><button class="w-full rounded-xl bg-teal px-4 py-3 font-semibold text-white">Create staff account</button></div></form></aside></div>
<div id="edit-user-modal" class="fixed inset-0 z-50 hidden items-center justify-center bg-navy/50 p-4"><div class="max-h-full w-full max-w-lg overflow-y-auto rounded-2xl bg-white p-6 shadow-xl"><div class="flex items-center justify-between"><h2 class="text-lg font-bold">Edit user</h2><button type="button" onclick="closeUserEdit()" class="rounded-lg p-1.5 text-navy/50 hover:bg-slate-100" aria-label="Close">&#10005;</button></div><form method="POST" action="{{ old('edit_action') }}" id="edit-user-form" class="mt-4 space-y-3">@csrf @method('PATCH')<input type="hidden" name="edit_action" value="{{ old('edit_action') }}"><input type="hidden" name="user_id" value="{{ old('user_id') }}"><div class="grid gap-3 sm:grid-cols-2">@foreach([['first_name','First name'],['middle_name','Middle name (optional)'],['last_name','Last name'],['suffix','Suffix (optional)'],['email','Email'],['phone_number','Philippine phone number'],['position','Position (optional)'],['department','Department (optional)']] as [$name,$label])<label class="block text-sm font-semibold">{{ $label }}<input name="{{ $name }}" value="{{ old($name) }}" @if(!str_contains($label,'optional')) required @endif class="mt-1 w-full rounded-xl border border-navy/15 p-2.5"></label>@endforeach<label class="block text-sm font-semibold">Role<select name="role" class="mt-1 w-full rounded-xl border border-navy/15 p-2.5">@foreach(['resident','staff','admin'] as $r)<option value="{{ $r }}" @selected(old('role')===$r)>{{ ucfirst($r) }}</option>@endforeach</select></label></div><label class="block text-sm font-semibold">New password (leave blank to keep current)<input type="password" name="password" class="mt-1 w-full rounded-xl border border-navy/15 p-2.5"></label><label class="block text-sm font-semibold">Confirm new password<input type="password" name="password_confirmation" class="mt-1 w-full rounded-xl border border-navy/15 p-2.5"></label><div class="flex gap-2 pt-1"><button type="button" onclick="closeUserEdit()" class="flex-1 rounded-xl border border-navy/15 px-4 py-2.5 font-semibold text-navy">Cancel</button><button class="flex-1 rounded-xl bg-teal px-4 py-2.5 font-semibold text-white">Save changes</button></div></form></div></div>
@if($errors->any() && old('edit_action'))<script>const m=document.getElementById('edit-user-modal');m.classList.remove('hidden');m.classList.add('flex');</script>@endif
<script>function openUserEdit(b){const d=b.dataset,f=document.getElementById('edit-user-form');f.action=d.action;f.elements.edit_action.value=d.action;f.elements.user_id.value=d.id;['first_name','middle_name','last_name','suffix','email','phone_number','position','department'].forEach(n=>{f.elements[n].value=d[n]||''});f.elements.role.value=d.role;f.elements.password.value='';f.elements.password_confirmation.value='';const m=document.getElementById('edit-user-modal');m.classList.remove('hidden');m.classList.add('flex');}function closeUserEdit(){const m=document.getElementById('edit-user-modal');m.classList.add('hidden');m.classList.remove('flex');}</script>
